210	            digitsEnd++;
211	        }
212	
213	        if (digitsStart == 0 || digitsStart == sitzplatz.Length || digitsEnd != sitzplatz.Length
214	            || !int.TryParse(sitzplatz[digitsStart..], out var columnNumber))
215	        {
216	            throw new FormatException($"Sitzplatz '{sitzplatz}' entspricht nicht dem Format <Reihenbuchstaben><Spaltenzahl>.");
217	        }
218	
219	        var rowLabel = sitzplatz[..digitsStart];
