1	using System.Text.Json;
2	using Microsoft.EntityFrameworkCore;
3	using Microsoft.EntityFrameworkCore.ChangeTracking;
4	using seed_a_backend.Api.Domain;
5	
6	namespace seed_a_backend.Api.Infrastructure;
7	
8	public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
9	{
10	    public DbSet<Venue> Venues => Set<Venue>();
11	    public DbSet<Room> Rooms => Set<Room>();
12	    public DbSet<Event> Events => Set<Event>();
13	    public DbSet<PriceCategory> PriceCategories => Set<PriceCategory>();
14	    public DbSet<Booking> Bookings => Set<Booking>();
15	    public DbSet<BookingPosition> BookingPositions => Set<BookingPosition>();
16	
17	    protected override void OnModelCreating(ModelBuilder modelBuilder)
18	    {
19	        modelBuilder.Entity<Venue>(entity =>
20	        {
21	            entity.HasMany(v => v.Rooms)
22	                .WithOne()
23	                .HasForeignKey(r => r.VenueId)
24	                .OnDelete(DeleteBehavior.Restrict);
25	        });
26	
27	        modelBuilder.Entity<Room>(entity =>
28	        {
29	            entity.HasMany(r => r.Events)
30	                .WithOne()
31	                .HasForeignKey(e => e.RoomId)
32	                .OnDelete(DeleteBehavior.Restrict);
33	
34	            entity.Property(r => r.RowLabels)
35	                .HasConversion(
36	                    v => JsonSerializer.Serialize(v, JsonSerializerOptions.Default),
37	                    v => JsonSerializer.Deserialize<List<string>>(v, JsonSerializerOptions.Default) ?? new List<string>())
38	                .Metadata.SetValueComparer(new ValueComparer<IReadOnlyList<string>>(
39	                    (a, b) => (a ?? new List<string>()).SequenceEqual(b ?? new List<string>()),
40	                    v => (v ?? new List<string>()).Aggregate(0, (hash, item) => HashCode.Combine(hash, item.GetHashCode())),
41	                    v => (v ?? new List<string>()).ToList()));
42	
43	            entity.Property(r => r.AisleColumns)
44	                .HasConversion(
45	                    v => JsonSerializer.Serialize(v, JsonSerializerOptions.Default),
46	                    v => JsonSerializer.Deserialize<List<int>>(v, JsonSerializerOptions.Default) ?? new List<int>())
47	                .Metadata.SetValueComparer(new ValueComparer<IReadOnlyCollection<int>>(
48	                    (a, b) => (a ?? new List<int>()).SequenceEqual(b ?? new List<int>()),
49	                    v => (v ?? new List<int>()).Aggregate(0, (hash, item) => HashCode.Combine(hash, item)),
50	                    v => (v ?? new List<int>()).ToList()));
51	        });
52	
53	        modelBuilder.Entity<Event>(entity =>
54	        {
55	            entity.HasMany(e => e.PriceCategories)
56	                .WithOne()
57	                .HasForeignKey(pc => pc.EventId)
58	                .OnDelete(DeleteBehavior.Cascade);
59	
60	            entity.HasMany(e => e.BookingPositions)
61	                .WithOne()
62	                .HasForeignKey(bp => bp.EventId)
63	                .OnDelete(DeleteBehavior.Restrict);
64	        });
65	
66	        modelBuilder.Entity<PriceCategory>(entity =>
67	        {
68	            entity.Property(pc => pc.Preis).HasPrecision(10, 2);
69	        });
70	
71	        modelBuilder.Entity<Booking>(entity =>
72	        {
