    [Fact]
    public async Task ImportAsync_wirft_bei_negativem_Preis_einer_Preiskategorie()
    {
        var ct = TestContext.Current.CancellationToken;
        await using var db = _database.CreateContext();
        var importer = new SeedDataImporter(db);
