/// </summary>
public class ProgramStartupTests
{
    private static string CreateIsolatedConnectionString()
    {
        var baseConnectionString = Environment.GetEnvironmentVariable("ConnectionStrings__Default")
            ?? throw new InvalidOperationException("ConnectionStrings__Default ist für die Tests nicht gesetzt.");

        var builder = new SqlConnectionStringBuilder(baseConnectionString)
        {
            InitialCatalog = $"seed_a_test_{Guid.NewGuid():N}",
        };
        return builder.ConnectionString;
    }

    [Fact]
    public async Task App_Start_migriert_das_Schema_und_importiert_den_Anfangsdatenbestand_gegen_eine_leere_DB()
    {
        var ct = TestContext.Current.CancellationToken;
        var connectionString = CreateIsolatedConnectionString();

        await using var factory = new WebApplicationFactory<Program>()
            .WithWebHostBuilder(webBuilder =>
                webBuilder.UseSetting("ConnectionStrings:Default", connectionString));

