            Assert.Equal(4, await db.Rooms.CountAsync(ct));
            Assert.Equal(6, await db.Events.CountAsync(ct));
        }
        finally
        {
            var options = new DbContextOptionsBuilder<AppDbContext>().UseSqlServer(connectionString).Options;
